new_shell=r'''function syncShell(){const morePages=['services','settings','share','analytics','reviews','subscription','profile'];root.querySelectorAll('.v2-sidebar nav [data-page],.v2-bottom [data-page]').forEach(el=>el.classList.toggle('active',el.dataset.page===S.page||el.dataset.page==='more'&&morePages.includes(S.page)));const back=root.querySelector('#app-back');if(back)back.hidden=S.tour||['dashboard','client','landing'].includes(S.page)}
function shell(){const simple=S.tour||!S.own&&!isClient()||S.page==='landing'||S.page==='register',signature=[simple,isClient(),!!S.me?.owner,!!S.preview].join(':');if(root.querySelector('.v2-layout')&&shellSignature===signature){syncShell();return}shellSignature=signature;const menu=nav().map(([p,i,t])=>`<button data-page="${p}" class="${S.page===p||p==='more'&&['services','settings','share','analytics','reviews','subscription','profile'].includes(S.page)?'active':''}">${icon(i)}<span>${t}</span></button>`).join('');root.innerHTML=`<div class="v2-layout ${simple?'simple':''} ${isClient()?'client-mode':''}">${!simple?`<aside class="v2-sidebar"><button class="brand" data-page="${isClient()?'client':'dashboard'}"><span class="brand-mark">т</span>${isClient()?esc(S.tenant?.name||'Моя запись'):'такт'}</button><p class="sidebar-caption">${isClient()?'Ваша страница записи':'Мой сервис онлайн-записи'}</p><nav>${menu}</nav><div class="sidebar-bottom">${isClient()?'Удобное время для вас':'Ваше дело. В вашем ритме.'}</div></aside>`:''}<main class="v2-main"><header class="v2-top"><button class="brand" data-page="${isClient()?'client':S.own?'dashboard':'landing'}"><span class="brand-mark">т</span>${isClient()?'Моя запись':'такт'}</button><div class="topbar-actions">${displayButton()}${S.me?.owner?'<button class="secondary admin-entry" data-page="admin">Админ-панель</button>':''}${!simple?`<button class="account-button" data-page="profile" aria-label="Мой профиль">${imageTag(c()?.photo,S.me?.name,'small-avatar')}</button>`:''}</div></header>${local?`<div class="demo-bar"><span>Локальная проверка</span><select id="demo-role" aria-label="Тестовая роль">${[['client','Клиент'],['company','Специалист'],['owner','Владелец']].map(([v,t])=>`<option value="${v}" ${S.role===v?'selected':''}>${t}</option>`).join('')}</select></div>`:''}${S.preview?'<div class="preview-banner">Так вашу страницу увидит клиент<button class="text-button" id="exit-preview">В кабинет</button></div>':''}<button id="app-back" class="text-button page-back" ${S.tour||['dashboard','client','landing'].includes(S.page)?'hidden':''}>← Назад</button><div id="view"></div><footer class="v2-footer"><span>${isClient()?'Онлайн-запись · Такт':'Такт · Ваше время принадлежит вам'}</span><button class="text-button" id="guide">Как это работает</button></footer></main>${!simple?`<nav class="v2-bottom" aria-label="Основная навигация">${menu}</nav>`:''}</div>`;syncShell()}'''
