new_data=r'''async function refreshOwn(){S.own=(await api('/companies'))[0]||null}
const fresh=(key,ttl=15000)=>Date.now()-(dataLoaded[key]||0)<ttl;
const invalidate=(...keys)=>keys.forEach(k=>dataLoaded[k]=0);
async function workData(force=false){if(!S.own)return false;if(!force&&fresh('work'))return false;const before=JSON.stringify([S.bookings,S.blocks]);const id=S.own.id;[S.bookings,S.blocks]=await Promise.all([api('/bookings?scope=company&company='+id),api('/v2/blocks?company='+id)]);dataLoaded.work=Date.now();return before!==JSON.stringify([S.bookings,S.blocks])}
async function loadPageData(page,force=false){let changed=false;if(!isClient()&&['dashboard','calendar','clients','analytics'].includes(page)){changed=await workData(force)||changed;if(page==='clients'&&(force||!fresh('clients'))){const before=JSON.stringify(S.clients);S.clients=await api('/v2/clients?company='+S.own.id);dataLoaded.clients=Date.now();changed=changed||before!==JSON.stringify(S.clients)}}if(!isClient()&&page==='reviews'&&(force||!fresh('reviews'))){const before=JSON.stringify(S.reviews);S.reviews=(await api('/v7/reviews?company='+S.own.id+'&limit=100')).items;dataLoaded.reviews=Date.now();changed=before!==JSON.stringify(S.reviews)||changed}if(isClient()&&page==='my'&&S.me&&(force||!fresh('my'))){const before=JSON.stringify(S.bookings);S.bookings=await api('/bookings');dataLoaded.my=Date.now();changed=before!==JSON.stringify(S.bookings)||changed}if(page==='admin'&&(force||!fresh('admin'))){const before=JSON.stringify(S.admin||null);S.admin=await api('/v5/admin');dataLoaded.admin=Date.now();changed=before!==JSON.stringify(S.admin)||changed}return changed}
function pageCached(page){if(!isClient()&&['dashboard','calendar','analytics'].includes(page))return !!dataLoaded.work;if(!isClient()&&page==='clients')return !!dataLoaded.work&&!!dataLoaded.clients;if(!isClient()&&page==='reviews')return !!dataLoaded.reviews;if(isClient()&&page==='my')return !S.me||!!dataLoaded.my;if(page==='admin')return !!dataLoaded.admin;return true}
function paintPage(view,page,version){if(version!==renderVersion||page!==S.page)return;const pages={admin:adminPage,landing,register:registration,dashboard,calendar:calendarPage,clients:clientsPage,more,services:servicesPage,share:sharePage,settings:settingsPage,reviews:reviewsPage,subscription:subscriptionPage,analytics:analyticsPage,client:clientPage,my:myBookings,profile};view.innerHTML=(pages[page]||landing)();view.classList.remove('screen-enter');void view.offsetWidth;view.classList.add('screen-enter');syncShell();if(page==='landing')requestAnimationFrame(()=>initLandingMotion());if(page==='settings')loadDeliveryStatus();if(page==='client'&&S.me&&!S.preview)loadClientNext()}
async function render({force=false}={}){const version=++renderVersion;if(S.page==='admin'&&!S.me?.owner)S.page='landing';if(isClient()&&!['client','my','profile','admin'].includes(S.page))S.page='client';if(!isClient()&&!S.own&&!['landing','register','admin'].includes(S.page))S.page='landing';shell();const page=S.page,view=document.querySelector('#view');if(S.tour&&page!=='admin'){view.innerHTML=tour();return}const cached=pageCached(page)&&!force;if(cached){paintPage(view,page,version);loadPageData(page,false).then(changed=>{if(changed&&version===renderVersion&&page===S.page){const y=scrollY;paintPage(view,page,version);requestAnimationFrame(()=>scrollTo({top:y,behavior:'auto'}))}}).catch(()=>{});return}view.innerHTML=skeleton();try{await loadPageData(page,true);paintPage(view,page,version)}catch(e){if(version===renderVersion)view.innerHTML=empty('Не удалось загрузить',e.message,'<button class="primary" id="refresh">Повторить</button>')}}'''
app=regex_once(app,r"async function refreshOwn\(\)\{[\s\S]*?\}\nfunction tour\(\)",new_data+"\nfunction tour()",'data/render cache')

